import{_ as i,l,o as e,c as s,v as t,p as n,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"MPC 应用","description":"","frontmatter":{"title":"MPC 应用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mpc-applications.md","filePath":"cs/mpc-applications.md","lastUpdated":1789023840000}'),h={name:"cs/mpc-applications.md"};function m(P,a,_,A,u,E){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="mpc-应用" tabindex="-1">MPC 应用 <a class="header-anchor" href="#mpc-应用" aria-label="Permalink to &quot;MPC 应用&quot;">​</a></h1><div class="epigraph"><p>多方计算让机构在不交出明文表的前提下算交集或统计。应用落点是反洗钱式的集合交集、联合分析；成本在通信轮次与恶意模型。</p><footer>—— 据 Yao；PSI 工程实践点名；对照[门限与 MPC 直觉](/cs/threshold-mpc)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/data-masking-tokenization">令牌化</a>仍有保险库明文。缺口是<strong>计算时也不集中表</strong>。密码学单元已有 MPC 直觉；本课应用与限制。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两家银行要比对客户重叠。明文交换违法或违约。PSI/MPC。缺口是：诚实多数假设、性能、谁看到输出。</p><h3 id="输出仍可能漏" tabindex="-1">输出仍可能漏 <a class="header-anchor" href="#输出仍可能漏" aria-label="Permalink to &quot;输出仍可能漏&quot;">​</a></h3><p>交集本身是信息。DP 可叠在输出上。</p><p><span class="marginnote">Yao；PSI 文献。PIR 下一课是检索隐私。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照令牌化中心。列出联合统计、PSI。下一课 PIR。</p>',12)),(e(),n(c,null,{default:o(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A7%81%E6%9C%89%E8%A1%A8%22%5D%20--%3E%20MPC%5B%22%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20B%5B%22%E7%A7%81%E6%9C%89%E8%A1%A8%22%5D%20--%3E%20MPC%0A%20%20MPC%20--%3E%20Y%5B%22%E5%8F%AA%E6%89%93%E5%BC%80%E7%BA%A6%E5%AE%9A%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>治理上的数据不出域。PIR 下一课是用户对数据库的隐私查询。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写部署到量化交易。PIR 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>令牌化仍有库；MPC 让计算分散。</li><li>输出策略与模型假设决定泄漏。</li><li>应用是交集与统计，不是万能。</li><li>下一课 PIR。</li><li>出处：Yao；对照 <a href="/cs/threshold-mpc">threshold-mpc</a>。</li></ul>',8))])}const b=i(h,[["render",m]]);export{C as __pageData,b as default};
